/* Bootstrap Bundle - Basic modal and dropdown functionality */
class Bootstrap {
  static Modal = class {
    constructor(element) {
      this.element = element;
    }
    
    show() {
      this.element.style.display = 'block';
      this.element.classList.add('show');
      document.body.classList.add('modal-open');
    }
    
    hide() {
      this.element.style.display = 'none';
      this.element.classList.remove('show');
      document.body.classList.remove('modal-open');
    }
    
    static getInstance(element) {
      return new Bootstrap.Modal(element);
    }
  }
  
  static Dropdown = class {
    constructor(element) {
      this.element = element;
    }
    
    toggle() {
      const menu = this.element.nextElementSibling;
      if (menu) {
        menu.classList.toggle('show');
      }
    }
    
    static getInstance(element) {
      return new Bootstrap.Dropdown(element);
    }
  }
}

// Basic modal functionality
document.addEventListener('DOMContentLoaded', function() {
  // Modal triggers
  document.querySelectorAll('[data-bs-toggle="modal"]').forEach(trigger => {
    trigger.addEventListener('click', function() {
      const target = document.querySelector(this.getAttribute('data-bs-target'));
      if (target) {
        const modal = new Bootstrap.Modal(target);
        modal.show();
      }
    });
  });
  
  // Modal close buttons
  document.querySelectorAll('[data-bs-dismiss="modal"]').forEach(closeBtn => {
    closeBtn.addEventListener('click', function() {
      const modal = this.closest('.modal');
      if (modal) {
        const modalInstance = new Bootstrap.Modal(modal);
        modalInstance.hide();
      }
    });
  });
  
  // Dropdown toggles
  document.querySelectorAll('[data-bs-toggle="dropdown"]').forEach(dropdown => {
    dropdown.addEventListener('click', function(e) {
      e.preventDefault();
      const dropdownInstance = new Bootstrap.Dropdown(this);
      dropdownInstance.toggle();
    });
  });
  
  // Close dropdowns when clicking outside
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.dropdown')) {
      document.querySelectorAll('.dropdown-menu.show').forEach(menu => {
        menu.classList.remove('show');
      });
    }
  });
});

window.bootstrap = Bootstrap;